import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long numberOfSquares = scanner.nextLong();
        scanner.close();
        System.out.println(findTheNumberOfLinesForLady(numberOfSquares));
    }

    static long findTheNumberOfLinesForLady(long forTheNumberOfSquares) {
        double a = Math.sqrt(forTheNumberOfSquares);
        long b = (long) Math.floor(a);
        if (a == b) return 2 * b;
        if (b * (b + 1) >= forTheNumberOfSquares) return 2 * b + 1;
        return 2 * b + 2;
    }
}

